// #121: files dragged from the file explorer over the page (flutter test --platform chrome, make
// test-web). Synthetic drag events with real File objects in a DataTransfer, as Chrome hands them to the
// page; the files are generated bytes.
@TestOn('browser')
library;

import 'dart:async';
import 'dart:js_interop';

import 'package:flutter_test/flutter_test.dart';
import 'package:web/web.dart' as web;
import 'package:woodshed_player/app/file_platform.dart';
import 'package:woodshed_player/app/file_platform_web.dart';

web.DragEvent drag(
  String type,
  web.DataTransfer data, [
  double x = 0,
  double y = 0,
]) => web.DragEvent(
  type,
  web.DragEventInit(
    dataTransfer: data,
    clientX: x.toInt(),
    clientY: y.toInt(),
    bubbles: true,
    cancelable: true,
  ),
);

web.DataTransfer files(Map<String, String> contents) {
  final data = web.DataTransfer();
  for (final e in contents.entries) {
    data.items.add(web.File([e.value.toJS].toJS, e.key));
  }
  return data;
}

const hangGuard = Duration(seconds: 30);

void main() {
  late WebFilePlatform platform;
  late List<FileDragEvent> events;
  setUp(() {
    platform = WebFilePlatform();
    events = [];
    platform.onFileDrag = events.add;
  });
  tearDown(() => platform.dispose());

  test('#121/AK4 files over the page report their position; leaving the page ends the hover', () {
    final data = files({'a.mp3': 'audio a'});
    final enter = drag('dragenter', data, 10, 20);
    web.document.body!.dispatchEvent(enter);
    expect(enter.defaultPrevented, isTrue);
    final over = drag('dragover', data, 12, 34);
    web.document.body!.dispatchEvent(over);
    expect(
      over.defaultPrevented,
      isTrue,
      reason: 'or the browser opens the file',
    );
    expect(events.single, isA<FileDragOver>());
    expect((events.single as FileDragOver).position, const Offset(12, 34));

    // entering a child element and leaving it again keeps the drag on the page
    web.document.body!.dispatchEvent(drag('dragenter', data));
    web.document.body!.dispatchEvent(drag('dragleave', data));
    expect(events, hasLength(1));
    web.document.body!.dispatchEvent(drag('dragleave', data));
    expect(events.last, isA<FileDragLeave>());
  });

  test('#121/AK1 dropped files are handed over in their order with the position, readable by the import', () async {
    final done = Completer<FileDragDrop>();
    platform.onFileDrag = (e) {
      events.add(e);
      if (e is FileDragDrop) done.complete(e);
    };
    final data = files({'b.mp3': 'audio b', 'a.wav': 'audio a'});
    web.document.body!.dispatchEvent(drag('dragenter', data));
    final drop = drag('drop', data, 40, 50);
    web.document.body!.dispatchEvent(drop);
    expect(drop.defaultPrevented, isTrue);
    // the files are read asynchronously; the guard only protects against a hang
    final dropped = await done.future.timeout(hangGuard);
    expect(dropped.position, const Offset(40, 50));
    expect(dropped.paths.map((p) => p.split('/').last), ['b.mp3', 'a.wav']);
    expect(
      String.fromCharCodes((await platform.take(dropped.paths.first))!),
      'audio b',
    );
    // a new drag starts from the page again
    web.document.body!.dispatchEvent(drag('dragenter', data));
    web.document.body!.dispatchEvent(drag('dragleave', data));
    expect(events.last, isA<FileDragLeave>());
  });

  test('#121 drags without files (text, links) are left to the page', () {
    final text = web.DataTransfer()..setData('text/plain', 'hello');
    final over = drag('dragover', text);
    web.document.body!.dispatchEvent(over);
    expect(over.defaultPrevented, isFalse);
    expect(events, isEmpty);
  });

  test('#121 after dispose the page no longer reports drags', () {
    platform.dispose();
    final over = drag('dragover', files({'a.mp3': 'x'}));
    web.document.body!.dispatchEvent(over);
    expect(over.defaultPrevented, isFalse);
    expect(events, isEmpty);
  });
}
